START TRANSACTION;UPDATE item_definitions SET display_name=CASE code WHEN 'ITEM-PENDANT-DRAW-QUIET' THEN '고요의 펜던트' WHEN 'ITEM-PENDANT-DRAW-OATH' THEN '맹세의 펜던트' WHEN 'ITEM-PENDANT-DRAW-RIFT' THEN '균열의 펜던트' WHEN 'ITEM-PENDANT-DRAW-STORM' THEN '폭풍의 펜던트' WHEN 'ITEM-PENDANT-DRAW-CRUEL' THEN '잔혹한 펜던트' WHEN 'ITEM-PENDANT-DRAW-STARS' THEN '별무리 펜던트' WHEN 'ITEM-PENDANT-DRAW-GREED' THEN '탐욕의 펜던트' WHEN 'ITEM-PENDANT-DRAW-FATE' THEN '운명의 펜던트' WHEN 'ITEM-PENDANT-DRAW-JUDGMENT' THEN '심판의 펜던트' WHEN 'ITEM-PENDANT-DRAW-THRONE' THEN '왕좌의 펜던트' WHEN 'ITEM-PENDANT-DRAW-SKY' THEN '천공의 펜던트' WHEN 'ITEM-PENDANT-DRAW-GENESIS' THEN '창세의 펜던트' WHEN 'ITEM-PENDANT-DRAW-CREATION' THEN '창조의 펜던트' END,metadata_json=JSON_SET(metadata_json,'$.name',CASE code WHEN 'ITEM-PENDANT-DRAW-QUIET' THEN '고요의 펜던트' WHEN 'ITEM-PENDANT-DRAW-OATH' THEN '맹세의 펜던트' WHEN 'ITEM-PENDANT-DRAW-RIFT' THEN '균열의 펜던트' WHEN 'ITEM-PENDANT-DRAW-STORM' THEN '폭풍의 펜던트' WHEN 'ITEM-PENDANT-DRAW-CRUEL' THEN '잔혹한 펜던트' WHEN 'ITEM-PENDANT-DRAW-STARS' THEN '별무리 펜던트' WHEN 'ITEM-PENDANT-DRAW-GREED' THEN '탐욕의 펜던트' WHEN 'ITEM-PENDANT-DRAW-FATE' THEN '운명의 펜던트' WHEN 'ITEM-PENDANT-DRAW-JUDGMENT' THEN '심판의 펜던트' WHEN 'ITEM-PENDANT-DRAW-THRONE' THEN '왕좌의 펜던트' WHEN 'ITEM-PENDANT-DRAW-SKY' THEN '천공의 펜던트' WHEN 'ITEM-PENDANT-DRAW-GENESIS' THEN '창세의 펜던트' WHEN 'ITEM-PENDANT-DRAW-CREATION' THEN '창조의 펜던트' END,'$.icon',CASE code WHEN 'ITEM-PENDANT-DRAW-QUIET' THEN '🌙' WHEN 'ITEM-PENDANT-DRAW-OATH' THEN '🤍' WHEN 'ITEM-PENDANT-DRAW-RIFT' THEN '🕳️' WHEN 'ITEM-PENDANT-DRAW-STORM' THEN '🌪️' WHEN 'ITEM-PENDANT-DRAW-CRUEL' THEN '🩸' WHEN 'ITEM-PENDANT-DRAW-STARS' THEN '🌌' WHEN 'ITEM-PENDANT-DRAW-GREED' THEN '🪙' WHEN 'ITEM-PENDANT-DRAW-FATE' THEN '🎲' WHEN 'ITEM-PENDANT-DRAW-JUDGMENT' THEN '⚖️' WHEN 'ITEM-PENDANT-DRAW-THRONE' THEN '👑' WHEN 'ITEM-PENDANT-DRAW-SKY' THEN '🪽' WHEN 'ITEM-PENDANT-DRAW-GENESIS' THEN '🌠' WHEN 'ITEM-PENDANT-DRAW-CREATION' THEN '🪬' END) WHERE code LIKE 'ITEM-PENDANT-DRAW-%' AND code<>'ITEM-PENDANT-DRAW-TICKET';INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('PENDANT_PROBABILITY_READ','pendant_probability_read','VERIFIED_USER','SHADOW',1,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),version=VALUES(version);INSERT INTO command_aliases(command_text,command_code,active) VALUES('/펜던트확률','PENDANT_PROBABILITY_READ',1) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=1;COMMIT;
